import {scanTicket,parseTicket} from './scan.js?v=0.9.1';
import {imageCanvas} from './photo-tools.js?v=0.9.1';
const escape=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openTicketScanner(apply){const d=document.createElement('dialog');d.className='scanner-dialog';document.body.append(d);let stream=null,source=null,crop={x:.2,y:.18,w:.6,h:.62};const stop=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;};const close=()=>{stop();source&&(source.width=0);d.close();d.remove();};d.addEventListener('cancel',e=>{e.preventDefault();close();});const base=()=>{d.innerHTML=`<h2>Read a delivery ticket</h2><p>Frame the order number, customer name, phone and full address, including the apartment. Leave out the food list and background.</p><div class="actions"><button id="use-live-text" class="primary">iPhone text recognition (recommended)</button><button id="guided-camera">Experimental photo reader with rear-camera guide</button><label class="button-link">Choose photo / native camera<input type="file" id="scanner-file" accept="image/*" capture="environment" hidden></label></div><p class="muted">Use Apple Live Text on iPhone for the recommended local recognition path. The experimental browser reader can misread house numbers. Photos are never uploaded; the first browser-model download may take a moment.</p><p class="error" id="scanner-error" role="alert"></p><button id="scanner-close">Cancel</button>`;d.querySelector('#scanner-close').onclick=close;d.querySelector('#scanner-file').onchange=e=>{if(e.target.files[0])showCrop(e.target.files[0]).catch(error);};d.querySelector('#guided-camera').onclick=camera;d.querySelector('#use-live-text').onclick=liveText;};const error=e=>{const area=d.querySelector('#scanner-error');if(area)area.textContent=e.message;};
 const review=result=>{stop();d.innerHTML=`<form><h2>Check the scanned details</h2><p>Recognition can be wrong. Check every number, street direction and apartment against the ticket.</p>${[['name','Customer name'],['phone','Phone number'],['address','Full address and unit'],['ticket','Ticket number']].map(([key,label])=>`<label>${label}<input name="${key}" value="${escape(result[key])}" ${key==='address'?'required':''} ${key==='phone'?'type="tel"':''} placeholder="${result[key]?'':'Not recognized — enter or leave blank'}"></label>`).join('')}<label class="checkbox-label"><input type="checkbox" required> I checked these details against the ticket.</label><div class="actions"><button type="button" id="scanner-back">Try again</button><button class="primary" type="submit">Use checked details</button><button type="button" id="scanner-close">Cancel</button></div></form>`;d.querySelector('#scanner-back').onclick=base;d.querySelector('#scanner-close').onclick=close;d.querySelector('form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));apply(values);close();};};
 const liveText=()=>{stop();d.innerHTML=`<form><h2>Use Apple Live Text</h2><p>Tap the text box below, then use Scan Text from the iPhone editing/keyboard menu if available. Or open Camera or Photos, select the ticket text with Live Text, copy it, and return here to paste. Include the name, phone, street and apartment. This uses Apple’s recognition rather than the experimental browser reader.</p><label>Ticket text<textarea name="text" required placeholder="Paste the ticket text here"></textarea></label><div class="actions"><button type="submit" class="primary">Review extracted details</button><button type="button" id="scanner-back">Back</button><button type="button" id="scanner-close">Cancel</button></div></form>`;d.querySelector('#scanner-back').onclick=base;d.querySelector('#scanner-close').onclick=close;d.querySelector('form').onsubmit=e=>{e.preventDefault();review(parseTicket(new FormData(e.target).get('text')));};};
 const camera=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Guided camera unavailable. Use Choose photo / native camera.');stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{exact:'environment'},width:{ideal:1920},height:{ideal:1440}}});d.innerHTML=`<h2>Frame the customer details</h2><p>Keep the name, phone and full address inside the outline. Move close enough to read the small print.</p><div class="camera-frame"><video autoplay muted playsinline></video><div class="camera-guide"></div></div><div class="actions"><button class="primary" id="capture-ticket">Take photo</button><button id="torch" hidden>Flashlight</button><button id="scanner-close">Cancel</button></div><p class="error" id="scanner-error"></p>`;const video=d.querySelector('video');video.srcObject=stream;await video.play();d.querySelector('#scanner-close').onclick=close;const track=stream.getVideoTracks()[0];if(track.getCapabilities?.().torch){const torch=d.querySelector('#torch');torch.hidden=false;let on=false;torch.onclick=async()=>{try{on=!on;await track.applyConstraints({advanced:[{torch:on}]});torch.textContent=on?'Flashlight on':'Flashlight off';}catch(e){error(e);}};}d.querySelector('#capture-ticket').onclick=()=>{const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{stop();crop={x:.15,y:.15,w:.7,h:.7};showCrop(blob).catch(error);canvas.width=0;},'image/jpeg',.95);};}catch(e){stop();base();error(Error('Rear camera could not open here. Choose photo / native camera instead.'));}};
 const showCrop=async file=>{stop();source&&(source.width=0);source=await imageCanvas(file,2000);d.innerHTML=`<h2>Crop to customer details</h2><p>Drag the outline or its corners. Include the order number, name, phone, street and unit; exclude the food list.</p><div class="crop-stage"><canvas></canvas><div class="crop-selection"><span data-corner="nw"></span><span data-corner="ne"></span><span data-corner="sw"></span><span data-corner="se"></span></div></div><label>Fine rotation (degrees)<input id="scan-angle" type="range" min="-12" max="12" value="0" step="1"></label><p class="muted">Tilt correction is applied when reading. Move the phone parallel to the ticket when taking a new photo.</p><p id="scan-progress" role="status"></p><p id="scanner-error" class="error"></p><div class="actions"><button id="read-crop" class="primary">Read this area</button><button id="full-crop">Use whole photo</button><button id="scanner-close">Cancel</button></div>`;const preview=d.querySelector('canvas');preview.width=source.width;preview.height=source.height;preview.getContext('2d').drawImage(source,0,0);const box=d.querySelector('.crop-selection'),stage=d.querySelector('.crop-stage');const paint=()=>{box.style.left=crop.x*100+'%';box.style.top=crop.y*100+'%';box.style.width=crop.w*100+'%';box.style.height=crop.h*100+'%';};paint();box.onpointerdown=e=>{e.preventDefault();const start={...crop},x=e.clientX,y=e.clientY,rect=stage.getBoundingClientRect(),corner=e.target.dataset.corner;box.setPointerCapture(e.pointerId);box.onpointermove=ev=>{const dx=(ev.clientX-x)/rect.width,dy=(ev.clientY-y)/rect.height;if(!corner){crop.x=Math.max(0,Math.min(1-crop.w,start.x+dx));crop.y=Math.max(0,Math.min(1-crop.h,start.y+dy));}else{const left=corner.includes('w')?Math.max(0,Math.min(start.x+start.w-.12,start.x+dx)):start.x,top=corner.includes('n')?Math.max(0,Math.min(start.y+start.h-.12,start.y+dy)):start.y,right=corner.includes('e')?Math.min(1,Math.max(start.x+.12,start.x+start.w+dx)):start.x+start.w,bottom=corner.includes('s')?Math.min(1,Math.max(start.y+.12,start.y+start.h+dy)):start.y+start.h;crop={x:left,y:top,w:right-left,h:bottom-top};}paint();};box.onpointerup=()=>{box.onpointermove=null;};};d.querySelector('#scanner-close').onclick=close;d.querySelector('#full-crop').onclick=()=>{crop={x:0,y:0,w:1,h:1};paint();};d.querySelector('#read-crop').onclick=async()=>{const button=d.querySelector('#read-crop');button.disabled=true;try{const result=await scanTicket(file,message=>{if(d.open&&d.querySelector('#scan-progress'))d.querySelector('#scan-progress').textContent=message;},{crop,angle:Number(d.querySelector('#scan-angle').value)});if(d.open)review(result);}catch(e){error(e);}finally{if(button.isConnected)button.disabled=false;}};};base();d.showModal();}
